scripts.prebuild:
node -e "
const key = process.env.REACT_APP_MAPS_API_KEY || '';
const isBad = !key || /placeholder|your_|replace|example/i.test(key);
if (isBad) {
  console.warn('\n⚠️  WARNING: REACT_APP_MAPS_API_KEY is missing or looks like a placeholder.');
  console.warn('   The production bundle will contain a non-working key.\n' +
  '   For live deploys, either:\n' +
  '     1. export REACT_APP_MAPS_API_KEY=... before npm run build, OR\n' +
  '     2. Run with MAPS_API_KEY=... python deploy.py (it can override at deploy time).\n');
} else {
  console.log('✅ Maps API key present at build time (length ' + key.length + '). Remember to also set referrer restrictions for all target hosts (test.1ink.us, go.1ink.us, localhost).');
}
const {execSync}=require('child_process');
const hash=execSync('git rev-parse --short HEAD').toString().trim();
const ts=new Date().toISOString().replace('T',' ').substring(0,16)+' UTC';
process.env.REACT_APP_BUILD_VERSION=hash;
process.env.REACT_APP_BUILD_TIME=ts;
const fs=require('fs');
let e=fs.existsSync('.env.local')?fs.readFileSync('.env.local','utf8'):'';
e=e.replace(/^REACT_APP_BUILD_VERSION=.*$/m,'').replace(/^REACT_APP_BUILD_TIME=.*$/m,'').trim();
fs.writeFileSync('.env.local',(e?e+'\n':'')+'REACT_APP_BUILD_VERSION='+hash+'\nREACT_APP_BUILD_TIME='+ts+'\n');
console.log('Build: '+hash+' @ '+ts);
"

scripts.validate:maps-key:
node -e "
const k=process.env.REACT_APP_MAPS_API_KEY||''; const bad=!k||/placeholder|your_|replace/i.test(k);
console.log(bad ? '❌ Key missing or placeholder' : '✅ Key looks configured ('+k.length+' chars)');
process.exit(bad?1:0);
"
